-- Three rice- and oat-free Philippine home-cooking adaptations. FNRI ingredient-input estimates; not allergy certification.
-- Raw input quantities avoid assuming that cooked weight equals purchased raw weight.
-- Idempotent: matching names are left unchanged. No existing recipes are edited.
BEGIN;
DO $seed$
DECLARE r jsonb; recipe_id_new text; missing integer;
BEGIN
  FOR r IN SELECT value FROM jsonb_array_elements($recipes$[{"id":"rcp-combined-boiled-potatoes-and-carrots","name":"Boiled Potatoes and Carrots","type":"Breakfast","cookTime":25,"dietTags":["vegan","vegetarian","dairy_free","clinical_review_required"],"ingredients":[{"fct_id":"0178","name":"Potato","grams":180,"quantity":"180 g before cooking"},{"fct_id":"0312","name":"Carrot","grams":80,"quantity":"80 g before cooking"},{"fct_id":"1226","name":"Oil, coconut","grams":5,"quantity":"5 g before cooking"}],"steps":[{"title":"Weighed ingredient inputs","desc":"180 g Potato; 80 g Carrot; 5 g Oil, coconut. Quantities are prepared raw inputs before cooking; trimming losses, cooking water, fuel and preparation costs are excluded from the estimate."},{"title":"Preparation","desc":"Wash and peel the potatoes and carrot, weigh the listed prepared raw inputs, then cut into even pieces. Boil in plain water until tender and drain. Toss with the measured coconut oil and serve warm. This is a simple boiled-root-crop breakfast adaptation for Philippine home cooking."},{"title":"Serve the recorded portion","desc":"Serve the entire prepared batch as one portion. Do not add unlisted seasonings, sauces or toppings without repeating the ingredient checks. Calories and carbohydrate amounts are ingredient-input estimates, not an individualized diabetic meal prescription."},{"title":"Qualified review required","desc":"Research formulation awaiting nutritionist review. Renal mineral targets, phenylalanine targets and prescribed swallowing texture have not been validated. Product labels and preparation cross-contact must be checked. This recipe is not certified allergen-free or medically approved."}]},{"id":"rcp-combined-sauteed-cabbage-and-potatoes","name":"Sauteed Cabbage and Potatoes","type":"Lunch","cookTime":30,"dietTags":["vegan","vegetarian","dairy_free","clinical_review_required"],"ingredients":[{"fct_id":"0178","name":"Potato","grams":180,"quantity":"180 g before cooking"},{"fct_id":"0308","name":"Cabbage, green","grams":100,"quantity":"100 g before cooking"},{"fct_id":"0312","name":"Carrot","grams":80,"quantity":"80 g before cooking"},{"fct_id":"1226","name":"Oil, coconut","grams":7,"quantity":"7 g before cooking"}],"steps":[{"title":"Weighed ingredient inputs","desc":"180 g Potato; 100 g Cabbage, green; 80 g Carrot; 7 g Oil, coconut. Quantities are prepared raw inputs before cooking; trimming losses, cooking water, fuel and preparation costs are excluded from the estimate."},{"title":"Preparation","desc":"Wash, trim and weigh the prepared raw vegetables. Cut the potatoes into small cubes. Simmer the potato and carrot in a little plain water until almost tender. Add cabbage and the measured coconut oil, then stir and cook until tender. This is a simple ginisang gulay adaptation."},{"title":"Serve the recorded portion","desc":"Serve the entire prepared batch as one portion. Do not add unlisted seasonings, sauces or toppings without repeating the ingredient checks. Calories and carbohydrate amounts are ingredient-input estimates, not an individualized diabetic meal prescription."},{"title":"Qualified review required","desc":"Research formulation awaiting nutritionist review. Renal mineral targets, phenylalanine targets and prescribed swallowing texture have not been validated. Product labels and preparation cross-contact must be checked. This recipe is not certified allergen-free or medically approved."}]},{"id":"rcp-combined-squash-and-potato-vegetable-soup","name":"Squash and Potato Vegetable Soup","type":"Dinner","cookTime":30,"dietTags":["vegan","vegetarian","dairy_free","clinical_review_required"],"ingredients":[{"fct_id":"0178","name":"Potato","grams":180,"quantity":"180 g before cooking"},{"fct_id":"0491","name":"Squash fruit","grams":100,"quantity":"100 g before cooking"},{"fct_id":"0312","name":"Carrot","grams":50,"quantity":"50 g before cooking"},{"fct_id":"1226","name":"Oil, coconut","grams":5,"quantity":"5 g before cooking"}],"steps":[{"title":"Weighed ingredient inputs","desc":"180 g Potato; 100 g Squash fruit; 50 g Carrot; 5 g Oil, coconut. Quantities are prepared raw inputs before cooking; trimming losses, cooking water, fuel and preparation costs are excluded from the estimate."},{"title":"Preparation","desc":"Wash, peel or trim, and weigh the prepared raw vegetables. Cut into even pieces and simmer in about 350 ml plain water until tender. Stir in the measured coconut oil. This is a simple sinabawang gulay adaptation."},{"title":"Serve the recorded portion","desc":"Serve the entire prepared batch as one portion. Do not add unlisted seasonings, sauces or toppings without repeating the ingredient checks. Calories and carbohydrate amounts are ingredient-input estimates, not an individualized diabetic meal prescription."},{"title":"Qualified review required","desc":"Research formulation awaiting nutritionist review. Renal mineral targets, phenylalanine targets and prescribed swallowing texture have not been validated. Product labels and preparation cross-contact must be checked. This recipe is not certified allergen-free or medically approved."}]}]$recipes$::jsonb) LOOP
    IF EXISTS (SELECT 1 FROM public.recipes WHERE name = r->>'name' OR id = r->>'id') THEN CONTINUE; END IF;
    SELECT count(*) INTO missing FROM jsonb_array_elements(r->'ingredients') ingredient
      WHERE NOT EXISTS(SELECT 1 FROM public.fnri_food_composition f WHERE f.fct_id = ingredient->>'fct_id');
    IF missing > 0 THEN RAISE EXCEPTION 'Required FNRI raw ingredient missing'; END IF;
    INSERT INTO public.recipes(id,name,type,difficulty,cook_time_min,servings,cost,kcal,protein_g,carbs_g,fats_g,diet_tags,goal_tags)
      SELECT r->>'id',r->>'name',r->>'type','easy',(r->>'cookTime')::integer,1,0,
       round(sum(f.energy_kcal * (ingredient->>'grams')::numeric / 100)),
       round(sum(f.protein_g * (ingredient->>'grams')::numeric / 100),1),
       round(sum(f.available_carbohydrate_g * (ingredient->>'grams')::numeric / 100),1),
       round(sum(f.total_fat_g * (ingredient->>'grams')::numeric / 100),1),
       ARRAY(SELECT jsonb_array_elements_text(r->'dietTags')), ARRAY['improve_health','maintain']::text[]
      FROM jsonb_array_elements(r->'ingredients') ingredient JOIN public.fnri_food_composition f ON f.fct_id=ingredient->>'fct_id'
      RETURNING id INTO recipe_id_new;
    INSERT INTO public.recipe_ingredients(recipe_id,fct_id,name,grams,quantity,status,sort_order)
      SELECT recipe_id_new,ingredient->>'fct_id',ingredient->>'name',(ingredient->>'grams')::numeric,ingredient->>'quantity','avail',ordinality::integer-1
      FROM jsonb_array_elements(r->'ingredients') WITH ORDINALITY AS t(ingredient,ordinality);
    INSERT INTO public.recipe_steps(recipe_id,title,description,step_order)
      SELECT recipe_id_new,step->>'title',step->>'desc',ordinality::integer-1
      FROM jsonb_array_elements(r->'steps') WITH ORDINALITY AS t(step,ordinality);
    INSERT INTO public.recipe_steps(recipe_id,title,description,step_order) VALUES(recipe_id_new,'Nutrition and costing basis','Research recipe awaiting nutritionist review. Nutrition is estimated from the listed FNRI raw ingredient inputs, not measured cooked output. Price excludes cooking water, fuel, labour and any unlisted additions. Divide the prepared batch only if you also divide the displayed portion.',99);
  END LOOP;
END $seed$;
COMMIT;
SELECT name,type,kcal FROM public.recipes WHERE id IN ('rcp-combined-boiled-potatoes-and-carrots','rcp-combined-sauteed-cabbage-and-potatoes','rcp-combined-squash-and-potato-vegetable-soup') ORDER BY type;
